import { useCallback, useEffect, useRef } from 'react'
import { CustomText, InnerForm } from '../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../../../lang'
import { getItemDetailForm } from '../../constants'
import { ItemDetailFormStyle } from './index.style'

function ItemDetailForm (props) {
  const { handleGetSubmitMethods, preFormData } = props
  const itemForm = getItemDetailForm(preFormData)
  const itemFormRef = useRef('')
  const sendSubmitRef = useRef(true)

  const handleSubmit = useCallback(async (e) => {
    const responseDetailForm = await itemFormRef.current.handleSubmit(e)
    if (responseDetailForm && Object.keys(responseDetailForm).length > 0) {
      const finalData = {
        ...responseDetailForm
      }
      delete finalData.errorField
      return finalData
    }
  }, [])

  useEffect(() => {
    if (sendSubmitRef.current) {
      handleGetSubmitMethods('item-detail', handleSubmit)
      sendSubmitRef.current = false
    }
  }, [handleGetSubmitMethods, handleSubmit])

  return (
    <ItemDetailFormStyle>
      <CustomText
        size='15px'
        weight={700}
        color={AgentColorPallette.black}
        top='8px'
        bottom='5px'
      >
        {LANG_STRINGS.itemDetails}
      </CustomText>
      <InnerForm
        formData={itemForm}
        ref={itemFormRef}
      />
    </ItemDetailFormStyle>
  )
}

export default ItemDetailForm
