export const getItemDetailForm = (data) => {
  const transportType = get(data, 'policy_detail.transportation_type')
  const fields = [
    {
      type: 'autoSearchModal',
      placeholder: LANG_STRINGS.select,
      name: 'type_of_goods',
      data: TYPE_OF_GOODS,
      label: LANG_STRINGS.typeOfGood,
      dataKey: 'key',
      displayKey: 'value',
      defaultValue: get(data, 'policy_detail.type_of_goods', '')
    },
    {
      type: 'textarea',
      placeholder: LANG_STRINGS.insuredItemDetail,
      name: 'details',
      label: LANG_STRINGS.insuredItemDetail,
      dataKey: 'key',
      displayKey: 'value',
      defaultValue: get(data, 'policy_detail.details', ''),
      minLength: 10,
      maxLength: 300
    }
  ]
  if (transportType === 'sea') {
    fields.push({
      type: 'input',
      placeholder: LANG_STRINGS.registrationNumber,
      name: 'registration_number',
      label: LANG_STRINGS.registrationNumber,
      className: 'input-field',
      defaultValue: get(data, 'policy_detail.registration_number', ''),
      minLength: 3,
      maxLength: 60
    })
  }
  return { fields: [...fields] }
}

export const getDeliveryForm = (countryFlags = [], data) => {
  const transportType = get(data, 'policy_detail.transportation_type')
  let departureDate = ''
  if (get(data, 'policy_detail.departure_date', '')) {
    departureDate = moment(get(data, 'policy_detail.departure_date', ''), 'YYYY-MM-DD').format('DD/MM/YYYY')
  }
  let fields = []
  if (transportType === 'sea') {
    fields.push({
      type: 'autoSearchModal',
      placeholder: LANG_STRINGS.countryFlag,
      name: 'country',
      data: countryFlags,
      label: LANG_STRINGS.countryFlag,
      defaultValue: get(data, 'policy_detail.country', ''),
      dataKey: 'country_code',
      displayKey: 'country_name'
    })
  }
  fields = [
    ...fields,
    {
      type: 'dob',
      label: LANG_STRINGS.departureDate,
      defaultValue: departureDate,
      error: ERROR_LANG.invalidDateFormat,
      minType: 'days',
      min: 0,
      max: 30,
      className: 'input-field',
      name: 'dob'
    },
    {
      type: 'input',
      placeholder: LANG_STRINGS.travelNo,
      name: 'travel_number',
      label: LANG_STRINGS.travelNo,
      className: 'input-field',
      defaultValue: get(data, 'policy_detail.travel_number', ''),
      minLength: 3,
      maxLength: 60
    },
    {
      type: 'name',
      placeholder: LANG_STRINGS.recipientName,
      name: 'recipient_name',
      label: LANG_STRINGS.recipientName,
      className: 'input-field',
      defaultValue: get(data, 'policy_detail.recipient_name', '')
    }
  ]
  return { fields: [...fields] }
}

