import { get } from 'lodash'
import moment from 'moment'
import { useCallback, useEffect, useRef } from 'react'
import { CustomText, InnerForm } from '../../../../../../../components'
import AddressForm from '../../../../../../../components/AddressForm'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../../../lang'
import { getDeliveryForm } from '../../constants'
import { DeliveryFormStyle } from './index.style'
import { resetError, useErrorContextValue, useLoaderContextValue, updateLoader } from '@pasarpolis/common-react-hooks'
import ShowSnackbar from '../../../../../../../components/ShowNotification'
import { useGetCountryList } from '../../../../state/hooks/useMarineCargo'

function DeliveryForm (props) {
  const { handleGetSubmitMethods, preFormData } = props
  const [{ getCountryListData = {} }, getCountryListRequest] = useGetCountryList()
  const [{ GET_COUNTRY_LIST_LOADER }, dispatchLoader] = useLoaderContextValue()
  const [
    {
      GET_COUNTRY_LIST_ERROR, getCountryListStatus
    },
    dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    if (GET_COUNTRY_LIST_LOADER === undefined) {
      getCountryListRequest()
    }
  }, [getCountryListRequest, GET_COUNTRY_LIST_LOADER])

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_COUNTRY_LIST_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  useEffect(() => {
    if (GET_COUNTRY_LIST_ERROR && getCountryListStatus) {
      ShowSnackbar.error({
        visible: true,
        text: getCountryListStatus
      })
      dispatchError(resetError({
        getCountryListStatus: ''
      }))
    }
  }, [getCountryListStatus, GET_COUNTRY_LIST_ERROR,
    dispatchError
  ])

  const deliveryForm = getDeliveryForm(getCountryListData.data, preFormData)
  const deliveryFormRef = useRef()
  const originAddrFormRef = useRef()
  const destinationAddrFormRef = useRef()
  const sendSubmitRef = useRef(true)

  const handleSubmit = useCallback(async (e) => {
    const responseDeliveryForm = await deliveryFormRef.current.handleSubmit(e)
    const originAddress = await originAddrFormRef.current(e)
    const destinationAddress = await destinationAddrFormRef.current(e)

    if ((responseDeliveryForm && Object.keys(responseDeliveryForm).length > 0) && originAddress && destinationAddress) {
      const finalData = {
        ...responseDeliveryForm,
        departure_date: moment(responseDeliveryForm.dob, 'DD/MM/YYYY').format('YYYY-MM-DD'),
        start_date: moment(responseDeliveryForm.dob, 'DD/MM/YYYY').format('YYYY-MM-DD'),
        pickup_address: originAddress,
        delivery_address: destinationAddress
      }
      delete finalData.errorField
      delete finalData.dob
      return finalData
    }
  }, [])

  useEffect(() => {
    if (sendSubmitRef.current) {
      handleGetSubmitMethods('delivery-form', handleSubmit)
      sendSubmitRef.current = false
    }
  }, [handleGetSubmitMethods, handleSubmit])

  const handleGetAddressSubmit = useCallback((type, onSubmit) => {
    switch (type) {
      case 'origin-address':
        originAddrFormRef.current = onSubmit
        break
      case 'destination-address':
        destinationAddrFormRef.current = onSubmit
        break
      default:
        break
    }
  }, [])

  return (
    <DeliveryFormStyle>
      <CustomText
        size='15px'
        weight={700}
        color={AgentColorPallette.black}
        top='8px'
        bottom='5px'
      >
        {LANG_STRINGS.delivery}
      </CustomText>
      <InnerForm
        formData={deliveryForm}
        ref={deliveryFormRef}
      />
      <AddressForm
        key='origin-address'
        addressType='origin-address'
        address={get(preFormData, 'policy_detail.pickup_address', {})}
        labels={{
          province: LANG_STRINGS.provinceOfOrigin,
          city: LANG_STRINGS.cityOfOrigin,
          address: LANG_STRINGS.addressOfOrigin
        }}
        handleGetAddressSubmit={handleGetAddressSubmit}
      />
      <AddressForm
        key='destination-address'
        addressType='destination-address'
        address={get(preFormData, 'policy_detail.delivery_address', {})}
        labels={{
          province: LANG_STRINGS.provinceOfDestination,
          city: LANG_STRINGS.cityOfDestination,
          address: LANG_STRINGS.addressOfDestination
        }}
        handleGetAddressSubmit={handleGetAddressSubmit}
      />
      <ShowSnackbar hideOkay />
    </DeliveryFormStyle>
  )
}

export default DeliveryForm
