import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useMarineCargoStateValue } from '../../context'
import {
  changeDiscount, createApplication, getApplicationDetail, getCountryList, getCustomerApplicationDetail, getPackageDetail,
  getPackagesList, getRegionCodes, getShipMaterial, submitApplication, updateApplication, updateCustomerApplication
} from '../actions'

export const useMarineCargoServiceCall = (actionsCall = () => {}) => {
  const [cargoState, dispatch] = useMarineCargoStateValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }

  return [cargoState, request]
}

export const useGetRegionCodes = () => useMarineCargoServiceCall(getRegionCodes)
export const useGetPackages = () => useMarineCargoServiceCall(getPackagesList)
export const useGetPackageDetail = () => useMarineCargoServiceCall(getPackageDetail)
export const useGetShipMaterial = () => useMarineCargoServiceCall(getShipMaterial)
export const useCreateApplication = () => useMarineCargoServiceCall(createApplication)
export const useUpdateApplication = () => useMarineCargoServiceCall(updateApplication)
export const useUpdateCustomerApplication = () => useMarineCargoServiceCall(updateCustomerApplication)
export const useSubmitApplication = () => useMarineCargoServiceCall(submitApplication)
export const useChangeDiscount = () => useMarineCargoServiceCall(changeDiscount)
export const useGetApplicationDetail = () => useMarineCargoServiceCall(getApplicationDetail)
export const useGetCustomerApplicationDetail = () => useMarineCargoServiceCall(getCustomerApplicationDetail)
export const useGetCountryList = () => useMarineCargoServiceCall(getCountryList)
