import { Container, CustomText } from '../../../../../../components'
import StepsHeader from '../../../../../../components/StepsHeader'
import { MarineCargoApplicationStyle } from './index.style'
import { resetError, useErrorContextValue, useLoaderContextValue, updateLoader } from '@pasarpolis/common-react-hooks'
import { useGetApplicationDetail, useGetCustomerApplicationDetail, useUpdateApplication, useUpdateCustomerApplication } from '../../../state/hooks/useMarineCargo'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { getParamsFromUri } from '../../../../../../helpers/utility'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import SingleImgContainer from '../../../../../../components/SingleImgContainer'
import { withRouter } from 'react-router'
import ItemDetailForm from '../components/ItemDetailForm'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { KARGO_LANG } from '../../../lang'
import DeliveryForm from '../components/DeliveryForm'
import AttachmentForm from '../components/AttachmentsForm'
import { LANG_STRINGS } from '../../../../../../lang'
import { DisplayFlexRCC, Row } from '../../../../../../commonStyle/index.style'
import { KTP_IMG, SEND_GOLD_ICON, VEHICLE_BACK_IMG, VEHICLE_FACE_IMG } from '../../../../../../images'
import ImageGuideModal from '../../../../../../components/PolicyCustAgentForm/components/ImageGuideModal'
import CustomerDataForm from '../components/CustomerDataForm'
import get from 'lodash/get'
import ButtonWithIcon from '../../../../../../components/ButtonWithIcon'
import { getFromLocalStorageData, removeFromLocalStorageData, setToLocalStorage } from '../../../../../../helpers/localstorage'
import { AGENT_CARGO_FORM_DATA, CUSTOMER_FLOW } from '../../../../../../constants/cookies'
import isEmpty from 'lodash/isEmpty'
import HardCopySection from '../../../../../../components/HardCopySection'
import { useSaveCustomerData } from '../../../../../../state/globalState/hooks/useGlobalContext'
import isObject from 'lodash/isObject'

function MarineCargoApplication (props) {
  const itemDetailSubmit = useRef()
  const deliveryFormSubmit = useRef()
  const attachmentFormSubmit = useRef()
  const customerDataFormSubmit = useRef()
  const hardcopyFormSubmit = useRef()
  const showForm = useRef(false)
  const travelNo = useRef('')
  const departureDate = useRef('')

  let isCustomerForm = false

  if (window.location.href.includes('customer/')) {
    isCustomerForm = true
  }

  const [imageGuideParams, setImageGuideParams] = useState({})

  const policyId = getParamsFromUri.call({ props }, 'policyId')

  const savedCustomerDataToGlobalStore = useSaveCustomerData()
  const [{
    GET_APPLICATION_DETAIL_LOADER, GET_CUSTOMER_APPLICATION_DETAIL_LOADER,
    UPDATE_APPLICATION_LOADER, UPDATE_CUSTOMER_APPLICATION_LOADER
  }, dispatchLoader
  ] = useLoaderContextValue()
  const [{ getApplicationDetailData = {} }, getApplicationDetailRequest] = useGetApplicationDetail()

  const [{ getCustomerApplicationDetailData = {} }, getCustomerApplicationDetailRequest] = useGetCustomerApplicationDetail()
  const [, updateCustomerApplicationRequest] = useUpdateCustomerApplication()

  const [, updateApplicationRequest] = useUpdateApplication()
  const [
    {
      GET_CUSTOMER_APPLICATION_DETAIL_ERROR, getCustomerApplicationDetailStatus,
      GET_APPLICATION_DETAIL_ERROR, getApplicationDetailStatus,
      UPDATE_APPLICATION_ERROR, updateApplicationStatus,
      UPDATE_CUSTOMER_APPLICATION_ERROR, updateCustomerApplicationStatus
    },
    dispatchError
  ] = useErrorContextValue()

  const applicationData = useMemo(() => {
    let policyData = {}
    if (isCustomerForm) {
      policyData = getCustomerApplicationDetailData
    } else {
      policyData = getApplicationDetailData
    }
    const policyDetail = get(policyData, 'policy_detail', {})
    const localData = getFromLocalStorageData(AGENT_CARGO_FORM_DATA)
    if (!policyDetail.type_of_goods && !isEmpty(localData)) {
      return localData
    }
    return policyData
  }, [isCustomerForm, getCustomerApplicationDetailData,
    getApplicationDetailData
  ])

  const hardcopyEnabled = get(applicationData, 'hard_copy_enabled', false)

  useEffect(() => {
    if (applicationData?.policy_detail) {
      savedCustomerDataToGlobalStore({
        customer_name: applicationData?.policy_detail?.customer_data?.name,
        mobile_no: applicationData?.policy_detail?.customer_data?.mobile_no,
        customer_address: applicationData?.policy_detail?.customer_data?.customer_address
      })
    }
  }, [savedCustomerDataToGlobalStore, applicationData])

  useEffect(() => {
    if (isCustomerForm) {
      if (GET_CUSTOMER_APPLICATION_DETAIL_LOADER === undefined) {
        setToLocalStorage(CUSTOMER_FLOW, 'true')
        getCustomerApplicationDetailRequest({
          policyId: policyId
        })
      }
    } else {
      if (GET_APPLICATION_DETAIL_LOADER === undefined) {
        getApplicationDetailRequest({
          policyId: policyId
        })
      }
    }
  }, [getApplicationDetailRequest,
    GET_APPLICATION_DETAIL_LOADER, policyId,
    isCustomerForm, getCustomerApplicationDetailRequest,
    GET_CUSTOMER_APPLICATION_DETAIL_LOADER
  ])

  useEffect(() => {
    return () => {
      if (isCustomerForm) {
        removeFromLocalStorageData(CUSTOMER_FLOW, 'true')
      }
      dispatchLoader(updateLoader({
        GET_APPLICATION_DETAIL_LOADER: undefined,
        UPDATE_APPLICATION_LOADER: undefined,
        GET_CUSTOMER_APPLICATION_DETAIL_LOADER: undefined,
        UPDATE_CUSTOMER_APPLICATION_LOADER: undefined
      }))
    }
  }, [dispatchLoader, isCustomerForm])

  useEffect(() => {
    if (!isCustomerForm && GET_APPLICATION_DETAIL_ERROR && getApplicationDetailStatus) {
      ShowSnackbar.error({
        visible: true,
        text: getApplicationDetailStatus
      })
      dispatchError(resetError({
        getApplicationDetailStatus: ''
      }))
    }
    if (isCustomerForm && GET_CUSTOMER_APPLICATION_DETAIL_ERROR && getCustomerApplicationDetailStatus) {
      ShowSnackbar.error({
        visible: true,
        text: getCustomerApplicationDetailStatus
      })
      dispatchError(resetError({
        getCustomerApplicationDetailStatus: ''
      }))
    }

    if (!isCustomerForm && UPDATE_APPLICATION_ERROR && updateApplicationStatus) {
      ShowSnackbar.error({
        visible: true,
        text: updateApplicationStatus.replace('travel_no', travelNo.current).replace('departure_date', departureDate.current)
      })
      dispatchError(resetError({
        updateApplicationStatus: ''
      }))
    }

    if (isCustomerForm && UPDATE_CUSTOMER_APPLICATION_ERROR && updateCustomerApplicationStatus) {
      ShowSnackbar.error({
        visible: true,
        text: updateCustomerApplicationStatus.replace('travel_no', travelNo.current).replace('departure_date', departureDate.current)
      })
      dispatchError(resetError({
        updateCustomerApplicationStatus: ''
      }))
    }

    if (getCustomerApplicationDetailStatus === 'success' || getApplicationDetailStatus === 'success') {
      showForm.current = true
      if (isCustomerForm) {
        dispatchError(resetError({
          getCustomerApplicationDetailStatus: ''
        }))
      } else {
        dispatchError(resetError({
          getApplicationDetailStatus: ''
        }))
      }
    }

    if (isCustomerForm) {
      if (updateCustomerApplicationStatus === 'success') {
        dispatchError(resetError({
          updateCustomerApplicationStatus: ''
        }))
        props.history.push(`/customer/marine_cargo/packages/${policyId}/preview`)
      }
    } else {
      if (updateApplicationStatus === 'success') {
        dispatchError(resetError({
          updateApplicationStatus: ''
        }))
        props.history.push(`/marine_cargo/packages/${policyId}/preview`)
      }
    }
  }, [GET_APPLICATION_DETAIL_ERROR, getApplicationDetailStatus,
    UPDATE_APPLICATION_ERROR, updateApplicationStatus,
    props.history, dispatchError, policyId, GET_CUSTOMER_APPLICATION_DETAIL_ERROR,
    getCustomerApplicationDetailStatus, isCustomerForm, updateCustomerApplicationStatus,
    UPDATE_CUSTOMER_APPLICATION_ERROR
  ])

  const handleSubmit = useCallback(async (e, saveToLocalstorage = false) => {
    const itemDetailData = await itemDetailSubmit.current(e)
    const deliveryData = await deliveryFormSubmit.current(e)
    const attachmentData = await attachmentFormSubmit.current(e)
    const customerData = await customerDataFormSubmit.current(e)
    let hardCopyData = {}
    if (applicationData?.hard_copy_enabled) {
      hardCopyData = await HardCopySection.getHardCopyData(e)
    }

    let isValidHardCopy = true
    if (hardCopyData.hard_copy_required && !hardCopyData.isValid) {
      isValidHardCopy = false
    }
    if (itemDetailData && deliveryData && attachmentData && customerData && isValidHardCopy) {
      const finalData = {
        ...itemDetailData,
        ...deliveryData,
        ...attachmentData,
        ...customerData,
        hard_copy_required: false,
        ...hardCopyData,
        token: policyId
      }
      if (saveToLocalstorage) {
        setToLocalStorage(AGENT_CARGO_FORM_DATA, {
          ...applicationData,
          policy_detail: finalData,
          ...finalData
        })
        props.history.push('/agent-address')
      } else {
        removeFromLocalStorageData(AGENT_CARGO_FORM_DATA)
        travelNo.current = finalData.travel_number
        departureDate.current = finalData.departure_date
        if (isCustomerForm) {
          updateCustomerApplicationRequest({
            body: {
              code: applicationData.code,
              ...finalData
            },
            policyId: policyId
          })
        } else {
          updateApplicationRequest({
            body: {
              code: applicationData.code,
              ...finalData
            },
            policyId: policyId
          })
        }
      }
    }
  }, [updateApplicationRequest,
    policyId, updateCustomerApplicationRequest,
    isCustomerForm, applicationData, props.history
  ])

  const handleGetSubmitMethods = useCallback((formType, method) => {
    switch (formType) {
      case 'item-detail':
        itemDetailSubmit.current = method
        break
      case 'delivery-form':
        deliveryFormSubmit.current = method
        break
      case 'attachment-form':
        attachmentFormSubmit.current = method
        break
      case 'customer-data-form':
        customerDataFormSubmit.current = method
        break
      case 'hardcopy-detail':
        hardcopyFormSubmit.current = method
        break
      default:
        break
    }
  }, [])

  const getAttachmentsContainer = useCallback(() => {
    return (
      <Row align='center' justify='space-between'>
        <SingleImgContainer
          title={LANG_STRINGS.billAWB}
          imgUrl={VEHICLE_FACE_IMG}
          titleAlign='center'
        />
        <SingleImgContainer
          title={LANG_STRINGS.invoice}
          imgUrl={VEHICLE_BACK_IMG}
          titleAlign='center'
        />
      </Row>
    )
  }, [])

  const handleOpenImgModal = useCallback((title, containerType) => {
    let imgContainer = ''
    let modalTitle = ''
    let btmTitle = ''

    switch (containerType) {
      case 'ktp_url':
        modalTitle = LANG_STRINGS.ktpPhotoGuide
        btmTitle = LANG_STRINGS.makeSureKTPPhotoClear
        imgContainer = (
          <SingleImgContainer
            title={LANG_STRINGS.photoKTP}
            imgUrl={KTP_IMG}
            titlePosition='up'
            titleAlign='start'
          />
        )
        break
      case 'attachments':
        modalTitle = LANG_STRINGS.attachment
        btmTitle = ''
        imgContainer = getAttachmentsContainer()
        break
      default:
        break
    }
    setImageGuideParams({
      showImgModal: true,
      modalImgContainer: imgContainer,
      modalTitle: modalTitle,
      modalBottomTitle: btmTitle
    })
  }, [getAttachmentsContainer])

  const handleCloseImgModal = () => {
    setImageGuideParams({
      showImgModal: false,
      modalImgContainer: '',
      modalTitle: ''
    })
  }

  const handleCustomerAddressChange = useCallback((customerAddress) => {
    savedCustomerDataToGlobalStore({
      customer_address: customerAddress
    })
  }, [savedCustomerDataToGlobalStore])

  const handleCustomerFormChange = useCallback((value, name) => {
    const key = (name === 'name') ? 'customer_name' : name
    savedCustomerDataToGlobalStore({
      [key]: value
    })
  }, [savedCustomerDataToGlobalStore])

  return (
    <Container
      mitraHeader={isCustomerForm}
      title='Kargo'
      hideBottomTabs
      displayBackButton
      backBtnId='kargoStepBack_3'
      loader={UPDATE_APPLICATION_LOADER || GET_APPLICATION_DETAIL_LOADER || GET_CUSTOMER_APPLICATION_DETAIL_LOADER || UPDATE_CUSTOMER_APPLICATION_LOADER}
    >
      <MarineCargoApplicationStyle>
        <StepsHeader leftText={LANG_STRINGS.insuredObject} current={isCustomerForm ? '1' : '3'} totalSteps={isCustomerForm ? '4' : '7'} />
        {
          showForm.current && applicationData.id &&
            <div className='content'>
              <CustomText
                color={AgentColorPallette.regular}
                lineHeight={1.5}
                size='13px'
                weight={500}
              >
                {KARGO_LANG.completeFormStep4}
              </CustomText>
              <ItemDetailForm
                preFormData={applicationData}
                handleGetSubmitMethods={handleGetSubmitMethods}
              />
              <hr className='separator' />
              <DeliveryForm
                preFormData={applicationData}
                handleGetSubmitMethods={handleGetSubmitMethods}
              />
              <hr className='separator' />
              <AttachmentForm
                preFormData={applicationData}
                handleGetSubmitMethods={handleGetSubmitMethods}
                onGuideClick={() => handleOpenImgModal(LANG_STRINGS.attachment, 'attachments')}
              />
              <hr className='separator' />

              <CustomerDataForm
                preFormData={applicationData}
                handleGetSubmitMethods={handleGetSubmitMethods}
                onGuideClick={() => handleOpenImgModal(LANG_STRINGS.attachment, 'ktp_url')}
                onCustomerAddressChange={handleCustomerAddressChange}
                onCustomerFormChange={handleCustomerFormChange}
              />
              {
                hardcopyEnabled &&
                  <>
                    <hr className='separator' />
                    <HardCopySection
                      isHideSendToPP={
                        isObject(applicationData?.policy_detail?.provider_branch)
                          ? !applicationData?.policy_detail?.provider_branch?.tags?.includes('HEADQUARTER')
                          : false
                      }
                      isCustomerForm={isCustomerForm}
                      preFilledData={{
                        hard_copy_required: applicationData?.policy_detail?.hard_copy_required,
                        hard_copy_sent_to: applicationData?.policy_detail?.hard_copy_sent_to,
                        customer_address: applicationData?.policy_detail?.customer_data?.customer_address,
                        customer_name: applicationData?.policy_detail?.customer_data?.name,
                        mobile_no: applicationData?.policy_detail?.customer_data?.mobile_no,
                        hard_copy_address: applicationData?.policy_detail?.hard_copy_address,
                        hard_copy_recipient: applicationData?.policy_detail?.hard_copy_recipient,
                        hard_copy_recipient_mobile: applicationData?.policy_detail?.hard_copy_recipient_mobile
                      }}
                      proposedAdminFee={applicationData?.proposed_admin_fee}
                      isHardCopyRequired={applicationData?.product?.always_charge_hard_copy}
                    />
                  </>
              }
              <div className='bottom-action-container'>
                <DisplayFlexRCC className='bottom-continue-btn'>
                  <ButtonWithIcon
                    id='cargoStepSubmit_3'
                    className='start-btn'
                    text={LANG_STRINGS.next}
                    icon={SEND_GOLD_ICON}
                    iconRight
                    onClick={handleSubmit}
                  />
                </DisplayFlexRCC>
              </div>
            </div>
        }
        <ImageGuideModal
          showImgModal={imageGuideParams.showImgModal}
          title={imageGuideParams.modalTitle}
          onClose={handleCloseImgModal}
          modalImgContainer={imageGuideParams.modalImgContainer}
          bottomTitle={imageGuideParams.modalBottomTitle}
        />
        <ShowSnackbar hideOkay />
      </MarineCargoApplicationStyle>
    </Container>
  )
}

export default withRouter(MarineCargoApplication)
