import get from 'lodash/get'
import { useCallback, useEffect, useRef } from 'react'
import { CustomText, InnerForm } from '../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../../../lang'
import { getAttachmentForm } from '../../constants'

function AttachmentForm (props) {
  const { handleGetSubmitMethods, preFormData, onGuideClick } = props
  const attachmentForm = getAttachmentForm(preFormData)
  const attachmentFormRef = useRef('')

  const handleSubmit = useCallback(async (e) => {
    const responseAttachmentForm = await attachmentFormRef.current.handleSubmit(e)
    if (responseAttachmentForm && Object.keys(responseAttachmentForm).length > 0) {
      const finalData = {
        bill_url: typeof responseAttachmentForm.bill_url === 'string' ? responseAttachmentForm?.bill_url : get(responseAttachmentForm, 'bill_url.bill_url'),
        invoice_url: typeof responseAttachmentForm.invoice_url === 'string' ? responseAttachmentForm?.invoice_url : get(responseAttachmentForm, 'invoice_url.invoice_url')
      }
      delete finalData.errorField
      return finalData
    }
  }, [])

  useEffect(() => {
    handleGetSubmitMethods('attachment-form', handleSubmit)
  }, [handleGetSubmitMethods, handleSubmit])

  return (
    <div>
      <CustomText
        size='15px'
        weight={700}
        color={AgentColorPallette.black}
        top='8px'
        bottom='5px'
      >
        {LANG_STRINGS.attachment}
      </CustomText>
      <InnerForm
        formData={attachmentForm}
        ref={attachmentFormRef}
        onGuideClick={onGuideClick}
      />
    </div>
  )
}

export default AttachmentForm
